def balanced(expr):
    stk = []
    pairs = {")": "(", "]": "[", "}": "{"}
    for ch in expr:
        if ch in "([{":
            stk.append(ch)
        elif ch in ")]}":
            if not stk or stk.pop() != pairs[ch]:
                return False
    return len(stk) == 0
