def to_postfix(infix):
    prec = {"+": 1, "-": 1, "*": 2, "/": 2}
    stk = []
    out = ""
    for ch in infix:
        if ch.isalnum():
            out += ch
        elif ch == "(":
            stk.append(ch)
        elif ch == ")":
            while stk[-1] != "(":
                out += stk.pop()
            stk.pop()
        else:
            while stk and stk[-1] != "(" and prec[stk[-1]] >= prec[ch]:
                out += stk.pop()
            stk.append(ch)
    while stk:
        out += stk.pop()
    return out

def eval_postfix(tokens):
    stk = []
    for t in tokens.split():
        if t.isdigit():
            stk.append(int(t))
        else:
            b = stk.pop()
            a = stk.pop()
            if t == "+": stk.append(a + b)
            elif t == "-": stk.append(a - b)
            elif t == "*": stk.append(a * b)
            elif t == "/": stk.append(a / b)
    return stk.pop()

